/* =========== 1. C'EST DU FRANÇAIS ? =========== */
function rMonde(el){
  el.innerHTML=head(['CO'],'1. C\'est du français ? 🌍')+consigne('L_c1')+`<div class="hero" style="max-width:1000px">${IMG('monde','wide')}</div>`;
  const items=shuffle([{w:'Bonjour',fr:1,g:'M'},{w:'Merci',fr:1,g:'F'},{w:'Salut',fr:1,g:'Tg'},{w:'Bonsoir',fr:1,g:'Sm'},{w:'Hola',l:'es-ES'},{w:'Hello',l:'en-GB'},{w:'Ciao',l:'it-IT'},{w:'Guten Tag',l:'de-DE'},{w:'Jambo',l:'sw-KE'},{w:'Olá',l:'pt-BR'}]);
  const g=document.createElement('div');g.className='grid g4';el.appendChild(g);const fb=document.createElement('div');fb.className='fb';fb.style.textAlign='center';el.appendChild(fb);
  let found=0,err=0;
  items.forEach((it,i)=>{const c=document.createElement('div');c.className='card pick';if(i===0)c.dataset.hint=1;
    c.innerHTML=`<div class="lab"><span class="box">✓</span><span class="big" style="flex:1">${it.w}</span></div><div class="row" style="justify-content:flex-end">${A(it.w,it.g||'M',it.fr?null:it.l)}</div>`;
    c.onclick=()=>{if(c.classList.contains('ok'))return;
      if(it.fr){c.classList.add('ok');found++;speak(it.w,{g:it.g});if(found===4){setFb(fb,true,fbOK('bravo','Bonjour · Merci · Salut · Bonsoir 🇫🇷'));award('monde','CO',err<=1?2:1,2);doneK('monde');confetti();}}
      else{err++;c.classList.add('ko');setTimeout(()=>c.classList.remove('ko'),500);setFb(fb,false,`❌ ${fr('notFr')} ${T('notFr')}`);}};
    g.appendChild(c);});
  const ZONES=[['🌍','Afrique',[['DZ','Algérie'],['BJ','Bénin'],['BF','Burkina Faso'],['BI','Burundi'],['CM','Cameroun'],['KM','Comores'],['CG','Congo (République du Congo)'],['CI','Côte d\'Ivoire'],['DJ','Djibouti'],['GA','Gabon'],['GN','Guinée'],['GQ','Guinée équatoriale'],['MG','Madagascar'],['ML','Mali'],['MA','Maroc'],['MU','Maurice'],['MR','Mauritanie'],['NE','Niger'],['CF','République centrafricaine'],['CD','République démocratique du Congo'],['RW','Rwanda'],['SN','Sénégal'],['SC','Seychelles'],['TD','Tchad'],['TG','Togo'],['TN','Tunisie']]],
    ['🌎','Amérique',[['CA','Canada'],['HT','Haïti'],['GF','Guyane (France)'],['GP','Guadeloupe (France)'],['MQ','Martinique (France)']]],
    ['🌍','Europe',[['AD','Andorre'],['BE','Belgique'],['FR','France'],['LU','Luxembourg'],['MC','Monaco'],['CH','Suisse']]],
    ['🌏','Asie',[['KH','Cambodge'],['LA','Laos'],['LB','Liban'],['VN','Viêt Nam']]],
    ['🌏','Océanie',[['NC','Nouvelle-Calédonie (France)'],['PF','Polynésie française (France)'],['VU','Vanuatu']]]];
  el.insertAdjacentHTML('beforeend',`<div class="memo"><h3>💡 ${fr('L_know')} ${T('L_know')}</h3>
   <p class="big" style="margin:0;font-size:23.2px">👥 ${fr('L_franco')} ${A(fr('L_franco'))}</p><p style="margin:4px 0 0">${T('L_franco')}</p>
   <p class="small" style="margin:4px 0 0">Sources : OIF, <i>La langue française dans le monde</i> (2026) · U.S. Census Bureau (population mondiale, 2026)</p>
   <h3 style="margin-top:16px">🗺️ ${fr('L_where')} ${A(fr('L_where'))} ${T('L_where')}</h3>
   ${ZONES.map(([ic,z,cs])=>`<div class="zone"><b class="zt">${ic} ${z}</b><div class="ctys">${cs.map(([iso,n])=>`<button type="button" class="cty" data-t="${esc(n.replace(/ \(.*\)$/,''))}"><span class="fl">${FLAG(iso)}</span>${n}</button>`).join('')}</div></div>`).join('')}</div>`);
  el.querySelectorAll('.cty').forEach(b=>b.onclick=()=>speak(b.dataset.t,{g:'M'}));
}

/* =========== 2. J'ÉCOUTE =========== */
const DIALS=[
 {k:'L_d1',img:'matin',lines:[['Le boulanger','Sm','Bonjour, madame !'],['La maman','F','Bonjour, monsieur !'],['La petite fille','C','Bonjour !']]},
 {k:'L_d2',img:'librairie',lines:[['Le garçon','Tb','Merci ! Au revoir, madame !'],['La libraire','F','Au revoir ! Bon après-midi !']]},
 {k:'L_d3',img:'soirFamille',lines:[['Le petit garçon','C','Bonsoir, mamie !'],['Le papa','M','Bonsoir, maman !'],['La grand-mère','Sf','Bonsoir !']]},
 {k:'L_d4',img:'salutAmis',lines:[['Mei','Tg','Salut ! Ça va ?'],['Aline','Tg2','Ça va, merci !']]}];
function rDialogues(el){
  el.innerHTML=head(['CO'],'2. J\'écoute 🎧')+consigne('c2');
  let order=shuffle(DIALS);let n=0,pts=0;const okS=new Set();const box=document.createElement('div');el.appendChild(box);
  function show(){
    if(n>=order.length){const miss=order.filter(d=>!okS.has(d.k));if(LOCK&&miss.length){award('dial','CO',pts,4);box.innerHTML='';retryBox(box,miss.length,()=>{order=shuffle(miss);n=0;show();});return;}if(!miss.length)doneK('dial');box.innerHTML=`<div class="sit"><div class="xl">🏆 ${okS.size} / 4</div><p>${fr(pts>=3?'bravo':'again')} ${T(pts>=3?'bravo':'again')}</p></div>`;award('dial','CO',pts,4);if(pts>=3)confetti();paintTr(box);return;}
    const d=order[n];
    box.innerHTML=`<div class="row center"><span class="big">🎧 ${n+1} / ${order.length}</span></div>
      <div class="row center" style="margin:10px 0"><button class="btn jaune big pl" data-hint>▶ ${fr('listen')} ${T('listen')}</button><button class="btn sec big pls">🐢</button></div>
      <div class="grid g4f pics"></div><div class="fb" style="text-align:center"></div><div class="after"></div>`;
    $('.pl',box).onclick=()=>playLines(d.lines);$('.pls',box).onclick=()=>playLines(d.lines,{slow:true});
    const g=$('.pics',box),fb=$('.fb',box);let done=false;
    DIALS.forEach((x,i)=>{const c=document.createElement('div');c.className='card pick';c.innerHTML=IMG(x.img)+`<div class="lab"><span class="box">✓</span>${'ABCD'[i]}</div>`;
      c.onclick=()=>{if(done)return;done=true;stopAudio();c.classList.add('checked');const good=DIALS.indexOf(d);
        if(x.k===d.k){c.classList.add('ok');pts++;okS.add(d.k);setFb(fb,true,fbOK('bravo','— '+fr(d.k)+' '+T(d.k)));}
        else{c.classList.add('ko');g.children[good].classList.add('ok');setFb(fb,false,`❌ → ${'ABCD'[good]} : ${fr(d.k)} ${T(d.k)}`);}
        const a=$('.after',box);
        a.innerHTML=`<div class="grid g2" style="margin-top:16px;align-items:center"><div>${IMG(d.img)}</div><div>${d.lines.map(([nm,gg,t])=>bulle(nm,gg,t)).join('')}
          <div class="row" style="margin-top:12px"><button class="btn jaune sh">🔁 ${fr('L_rep')} ${T('L_rep')}</button><button class="btn nx">${n<order.length-1?fr('next'):fr('result')} → ${T(n<order.length-1?'next':'result')}</button></div></div></div>`;
        $('.sh',a).onclick=()=>playLines(d.lines,{gap:2600,each:i=>{a.querySelectorAll('.bulle').forEach((b,j)=>b.style.outline=j===i?'4px solid var(--corail)':'');},done:()=>a.querySelectorAll('.bulle').forEach(b=>b.style.outline='')});
        $('.nx',a).onclick=()=>{n++;show();};paintTr(a);};
      g.appendChild(c);});
    paintTr(box);setTimeout(()=>playLines(d.lines),500);
  }
  show();
}

/* =========== 3. LES MOTS =========== */
const MOTS=[
 {w:'Bonjour !',img:'matin',g:'F',s:'Bonjour, monsieur !',sg:'F'},
 {w:'Bon après-midi !',img:'librairie',g:'F',s:'Au revoir ! Bon après-midi !',sg:'F'},
 {w:'Bonsoir !',img:'soirFamille',g:'Sf',s:'Bonsoir, maman !',sg:'M'},
 {w:'Salut !',img:'salutAmis',g:'Tg',s:'Salut ! Ça va ?',sg:'Tg'},
 {w:'Ça va ?',img:'cava',g:'Sm',s:'Ça va, merci !',sg:'Sm2'},
 {w:'Merci !',img:'merci',g:'M',s:'Merci, madame !',sg:'M'},
 {w:'Au revoir !',img:'finCours',g:'F',s:'Merci ! Au revoir !',sg:'M'},
 {w:'Bonne soirée !',img:'bureauSoir',g:'F',s:'Au revoir ! Bonne soirée !',sg:'M'}];
function rMots(el){
  el.innerHTML=head(['CO','EO','LG'],'3. Les mots 🃏')+video('mots',true)+consigne('L_c3');
  const box=document.createElement('div');el.appendChild(box);const th=document.createElement('div');th.className='thumbs';el.appendChild(th);
  const done=new Set();let i=0;
  MOTS.forEach((m,k)=>{const t=document.createElement('button');t.className='thumb';t.innerHTML=`<img src="${PIC(m.img)}" alt="">${m.w}`;t.onclick=()=>{i=k;show();};th.appendChild(t);});
  function show(){stopAudio();stopRec();const m=MOTS[i];
    th.querySelectorAll('.thumb').forEach((t,k)=>{t.classList.toggle('on',k===i);t.classList.toggle('done',done.has(k));});
    box.innerHTML=`<div class="carou"><div>${IMG(m.img)}</div><div class="cside">
      <div class="small">${i+1} / ${MOTS.length}</div>
      <span class="lvl">1 · ${fr('L_word')} ${T('L_word')}</span>
      <div class="xl" style="margin:8px 0">${m.w}</div><div>${A(m.w,m.g)}</div>
      <div class="tri big" style="display:block;font-size:20.8px;margin:6px 0" data-k="${EXP[m.w]}"></div>
      <div class="r3" style="margin-top:10px"></div>
      <hr class="sep">
      <span class="lvl">2 · ${fr('L_sent')} ${T('L_sent')}</span>
      <div class="big" style="margin:8px 0">${S(m.s,m.sg)}</div><div>${T(EXP[m.s])}</div>
      <div style="margin-top:12px">${micBtn()}</div><p class="small" style="margin:6px 0 0">${fr('L_c3b')} ${T('L_c3b')}</p>
      <div class="row center" style="margin-top:16px"><button class="btn sec pv" ${i===0?'disabled':''}>◀</button><button class="btn nx">▶</button></div>
    </div></div>`;
    repeat3($('.r3',box),m.w,m.g,()=>{done.add(i);award('rep'+i,'EO',1,1);th.children[i].classList.add('done');if(done.size===MOTS.length){doneK('mots');confetti();toast('👏 '+fr('bravo'));}});
    $('.r3 .rp',box).dataset.hint=1;
    $('.pv',box).onclick=()=>{if(i>0){i--;show();}};$('.nx',box).onclick=()=>{i=(i+1)%MOTS.length;show();};
    paintTr(box);bindMics(box);setTimeout(()=>speak(m.w,{g:m.g}),350);
  }
  show();
  el.insertAdjacentHTML('beforeend',cahier(1,'nb1',CAH[1]()));
}

/* =========== 4. MATIN, APRÈS-MIDI, SOIR =========== */
function rMoment(el){
  el.innerHTML=head(['CO','CE','LG'],'4. Bonjour, bon après-midi ou bonsoir ? ☀️🌤️🌙')+video('moment',true)+`
   <div class="timeline">
    <div class="tcard tc-m"><div class="big">☀️ ${fr('L_mat')}</div>${T('L_mat')}<div class="clock">🕗 8 h</div>${IMG('matin')}<div style="margin-top:10px">${SW('Bonjour !','F')}</div></div>
    <div class="tcard tc-a"><div class="big">🌤️ ${fr('L_apm')}</div>${T('L_apm')}<div class="clock">🕒 15 h</div>${IMG('librairie')}<div style="margin-top:10px">${SW('Bon après-midi !','F')}</div></div>
    <div class="tcard tc-s"><div class="big">🌙 ${fr('L_soir')}</div>${T('L_soir')}<div class="clock">🕗 20 h</div>${IMG('soirFamille')}<div style="margin-top:10px">${SW('Bonsoir !','Sf')}</div></div>
   </div>
   <div class="rule">
    <div class="rcol arr"><h3><span class="badge arr">🚪➡️ ${fr('L_arr')}</span> ${T('L_arr')}</h3>
      <div class="li">☀️🌤️ ${SW('Bonjour !','M')}</div><div class="li" style="margin-top:8px">🌙 ${SW('Bonsoir !','M')}</div></div>
    <div class="rcol dep"><h3><span class="badge dep">👋🚪 ${fr('L_dep')}</span> ${T('L_dep')}</h3>
      <div class="li">${SW('Au revoir !','F')}</div><div class="li" style="margin-top:8px">🌤️ ${SW('Bon après-midi !','F')}</div><div class="li" style="margin-top:8px">🌙 ${SW('Bonne soirée !','F')}</div></div>
   </div>
   <div class="memo">🇨🇦 ${fr('L_qc')} ${T('L_qc')}</div>
   <div style="margin-top:26px">${consigne('L_c4')}</div>`;
  let Q=shuffle([
   {img:'matin',h:'🕗 8 h',a:'arr',ans:'Bonjour !',o:['Bonjour !','Bonsoir !','Bonne soirée !']},
   {img:'librairie',h:'🕒 15 h',a:'dep',ans:'Bon après-midi !',o:['Bon après-midi !','Bonsoir !','Bonjour !']},
   {img:'soirFamille',h:'🕗 20 h',a:'arr',ans:'Bonsoir !',o:['Bonjour !','Bonsoir !','Bon après-midi !']},
   {img:'travail9',h:'🕘 9 h',a:'arr',ans:'Bonjour !',o:['Bonsoir !','Bonjour !','Bonne soirée !']},
   {img:'resto',h:'🕢 19 h 30',a:'arr',ans:'Bonsoir !',o:['Bonjour !','Bon après-midi !','Bonsoir !']},
   {img:'bureauSoir',h:'🕖 19 h',a:'dep',ans:'Bonne soirée !',o:['Bonne soirée !','Bonjour !','Bon après-midi !']}]);
  let i=0,pts=0;const good=new Set(),ALLQ=Q.length;const box=document.createElement('div');el.appendChild(box);
  function show(){
    if(i>=Q.length){const miss=Q.filter(q=>!good.has(q));if(LOCK&&miss.length){award('moment','CE',pts,ALLQ);box.innerHTML='';retryBox(box,miss.length,()=>{Q=shuffle(miss);i=0;show();});return;}if(!miss.length)doneK('moment');box.innerHTML=`<div class="sit"><div class="xl">🏆 ${good.size} / ${ALLQ}</div><div class="row center" style="margin-top:10px"><button class="btn sec ag">↻</button></div></div>`;$('.ag',box).onclick=()=>{i=0;pts=0;good.clear();show();};award('moment','CE',pts,Q.length);if(pts>=5)confetti();return;}
    const q=Q[i];
    box.innerHTML=`<p class="small" style="text-align:center">${i+1} / ${Q.length}</p><div class="hero" style="max-width:720px">${IMG(q.img)}</div>
      <div class="row center"><span class="badge">${q.h}</span><span class="badge ${q.a}">${q.a==='arr'?'🚪➡️ '+fr('L_arr'):'👋🚪 '+fr('L_dep')}</span>${T(q.a==='arr'?'L_arr':'L_dep')}</div>
      <div class="row center opts2" style="margin-top:12px"></div><div class="fb" style="text-align:center"></div>`;
    const r=$('.opts2',box),fb=$('.fb',box);
    shuffle(q.o).forEach((o,j)=>{const w=document.createElement('span');w.className='opt';const b=choice(o);if(j===0)b.dataset.hint=1;w.appendChild(b);w.insertAdjacentHTML('beforeend',A(o));
      b.onclick=()=>{r.querySelectorAll('.choice').forEach(x=>x.disabled=true);
        if(o===q.ans){b.classList.add('ok');pts++;good.add(q);setFb(fb,true,fbOK());}else{b.classList.add('ko');setFb(fb,false,`❌ → ${q.ans}`);}
        const cur=i;speakSafe(q.ans,{},()=>setTimeout(()=>{if(box.isConnected&&i===cur){i++;show();}},900));};r.appendChild(w);});
    paintTr(box);
  }
  show();
  fiBlock(el);
  el.insertAdjacentHTML('beforeend',cahier(2,'nb2',CAH[2]()));
}

