const crow=(t,g='M')=>`<div class="crow"><span class="cfr">${t}</span>${A(t,g)}${T(EXP[t])}</div>`;
const cgrp=(title,rows)=>`<div class="cgrp"><h4>${title}</h4>${rows}</div>`;
const crule=k=>`<div class="crule">📌 ${fr(k)} ${A(fr(k))} ${TB(k)}</div>`;
function cahier(id,titleKey,body){
  return `<section class="cahier" data-cah="${id}"><div class="chead"><span class="cico" aria-hidden="true">📓</span><div><div class="ck">${fr('nb_t')} ${T('nb_t')}</div><h3>${fr(titleKey)} ${T(titleKey)}</h3></div></div>
    <div class="gsay">${gAv('E')}<div class="gb"><b>Elara</b><div class="big" style="font-size:20px">✍️ ${S(fr('nb_copy'),'F')}</div>${TB('nb_copy')}</div></div>
    <div class="cbody">${body}</div>
    <div class="cact row center"><button type="button" class="btn sm cprint">🖨️ ${fr('nb_print')} ${T('nb_print')}</button><button type="button" class="btn sm jaune cpdf">⬇️ ${fr('nb_pdf')} ${T('nb_pdf')}</button><label class="btn sm sec cphoto">📷 ${fr('nb_photo')} ${T('nb_photo')}<input type="file" accept="image/*" capture="environment" hidden></label></div><div class="schip"></div></section>`;}
const CAH={
 1:()=>cgrp(`🚪➡️ ${fr('nb_greet')} ${T('nb_greet')}`,crow('Bonjour !')+crow('Bonsoir !')+crow('Salut !','Tg'))
   +cgrp(`💬 ${fr('nb_ask')} ${T('nb_ask')}`,crow('Ça va ?')+crow('Ça va !','F')+crow('Ça va, merci !','F'))
   +cgrp(`🙏 ${fr('nb_thank')} ${T('nb_thank')}`,crow('Merci !','F')+crow('Merci, madame !'))
   +cgrp(`👋🚪 ${fr('nb_leave')} ${T('nb_leave')}`,crow('Au revoir !')+crow('Bon après-midi !','F')+crow('Bonne soirée !','F')+crow('Salut !','Tg'))
   +cgrp(`🙂 ${fr('L_lv1')} ${T('L_lv1')}`,crow('madame')+crow('monsieur','F')),
 2:()=>cgrp(`🕗 ${fr('nb_when')} ${T('nb_when')}`,`<table class="ctab"><tr><th></th><th>🚪➡️ ${fr('L_arr')} ${T('L_arr')}</th><th>👋🚪 ${fr('L_dep')} ${T('L_dep')}</th></tr>
     <tr><th>☀️ ${fr('L_mat')}</th><td><b>Bonjour !</b> ${A('Bonjour !')}</td><td><b>Au revoir ! Bonne journée !</b> ${A('Au revoir ! Bonne journée !','F')}</td></tr>
     <tr><th>🌤️ ${fr('L_apm')}</th><td><b>Bonjour !</b> ${A('Bonjour !','F')}</td><td><b>Au revoir ! Bon après-midi !</b> ${A('Au revoir ! Bon après-midi !','F')}</td></tr>
     <tr><th>🌙 ${fr('L_soir')}</th><td><b>Bonsoir !</b> ${A('Bonsoir !')}</td><td><b>Au revoir ! Bonne soirée !</b> ${A('Au revoir ! Bonne soirée !','F')}</td></tr></table>`+crule('nb_r1')+crule('nb_r2'))
   +cgrp(`👔 ${fr('L_formal')} ${T('L_formal')} · ${fr('L_fw')} · ${fr('L_fs')}`,crow('Bonjour, madame !')+crow('Comment allez-vous ?','F')+crow('Très bien, merci. Et vous ?')+crow('Au revoir ! Bonne journée !','F'))
   +cgrp(`😊 ${fr('L_informal')} ${T('L_informal')} · ${fr('L_inf')}`,crow('Salut ! Ça va ?','Tg')+crow('Ça va bien, merci. Et toi ?','Tg2')+crow('À bientôt !','Tg')+crow('À demain !','Tg2'))
   +`<div class="cgrp">${crule('L_politeW')}${crule('L_salut')}</div>`,
 3:()=>CAH[1]()+CAH[2]()+cgrp(`🎵 ${fr('nb_sounds')} ${T('nb_sounds')}`,crule('nb_r3')+crule('ruleStress'))
   +cgrp(`🌍 ${fr('L_chez')} ${T('L_chez')}`,crule('L_frNote')+crule('L_qc'))};
let H2P=null;
const loadJs=src=>new Promise((res,rej)=>{const s=document.createElement('script');s.src=src;s.onload=()=>res();s.onerror=()=>rej(new Error('cdn'));document.head.appendChild(s);});
function loadH2P(){if(window.html2canvas&&window.jspdf)return Promise.resolve();if(H2P)return H2P;
  H2P=Promise.all([window.html2canvas?0:loadJs('https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js'),
                   window.jspdf?0:loadJs('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js')]).catch(e=>{H2P=null;throw e;});return H2P;}
function cahClone(sec){const c=sec.cloneNode(true);c.querySelectorAll('.cact,.schip,.aus,.gsay').forEach(x=>x.remove());
  const h=document.createElement('div');h.className='cpdfhead';h.innerHTML=`<b>French Practice Hub · Pré-A1.1</b> · ${LTITLE}${ME&&ME.name?' · 🙋 '+esc(ME.name):''}`;c.prepend(h);
  const w=document.createElement('div');w.id='fph-l1';w.className='fph-pdf';w.lang='fr';w.appendChild(c);return w;}
function cahPrint(sec){const host=document.createElement('div');host.className='fph-printhost';host.appendChild(cahClone(sec));document.body.appendChild(host);
  document.documentElement.classList.add('fph-printing');let done=false;
  const end=()=>{if(done)return;done=true;document.documentElement.classList.remove('fph-printing');host.remove();window.removeEventListener('afterprint',end);};
  window.addEventListener('afterprint',end);setTimeout(()=>{try{window.print();}catch(e){}setTimeout(end,1500);},60);}
async function cahPdf(sec,btn){btn.disabled=true;const t=btn.innerHTML;btn.innerHTML='⏳ PDF…';
  let host=null;
  try{await loadH2P();const node=cahClone(sec);
    /* rendu à largeur fixe (700 px = largeur utile d'une page A4), puis découpage en pages entre deux groupes */
    host=document.createElement('div');host.className='fph-pdfhost';host.style.cssText='position:fixed;left:0;top:0;width:700px;z-index:-1;pointer-events:none;opacity:0';host.appendChild(node);document.body.appendChild(host);
    const W=700,H=Math.ceil(node.scrollHeight)+16;
    const top0=node.getBoundingClientRect().top;
    const cuts=[...node.querySelectorAll('.cgrp,.crule,.ctab')].map(x=>Math.round(x.getBoundingClientRect().bottom-top0));
    const cv=await window.html2canvas(node,{scale:2,useCORS:true,backgroundColor:'#ffffff',logging:false,onclone:d=>d.querySelectorAll('.fph-pdfhost').forEach(h=>h.style.opacity='1'),width:W,height:H,windowWidth:window.innerWidth,windowHeight:window.innerHeight,scrollX:0,scrollY:0});
    const pdf=new window.jspdf.jsPDF({unit:'mm',format:'a4',orientation:'portrait'});
    const mm=190/W,pageH=Math.floor(272/mm),k=cv.width/W;let y=0,first=true;
    while(y<H-2){let end=(H-y)*mm<=279?H:Math.min(H,y+pageH);if(end<H){const c=cuts.filter(v=>v>y+120&&v<=end+1);if(c.length)end=Math.max(...c)+6;}if(H-end<60)end=H;
      const sl=document.createElement('canvas');sl.width=cv.width;sl.height=Math.ceil((end-y)*k);
      const g=sl.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,sl.width,sl.height);g.drawImage(cv,0,Math.floor(y*k),cv.width,sl.height,0,0,cv.width,sl.height);
      if(!first)pdf.addPage();first=false;let hm=(end-y)*mm,wm=190;if(hm>279){wm=190*279/hm;hm=279;}pdf.addImage(sl.toDataURL('image/jpeg',.92),'JPEG',10+(190-wm)/2,10,wm,hm);
      pdf.setFontSize(8);pdf.setTextColor(140);pdf.text('French Practice Hub · '+LTITLE,10,292);y=end;}
    pdf.save(`FPH-Lecon1-Mon-cahier-${sec.dataset.cah}.pdf`);}
  catch(e){console.warn(e);toast('🖨️ → PDF');cahPrint(sec);}
  if(host)host.remove();btn.disabled=false;btn.innerHTML=t;}
async function photoBlob(file){const url=URL.createObjectURL(file);try{const im=new Image();await new Promise((r,j)=>{im.onload=r;im.onerror=j;im.src=url;});
  const s=Math.min(1,1600/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*s);c.height=Math.round(im.height*s);
  c.getContext('2d').drawImage(im,0,0,c.width,c.height);return await new Promise(r=>c.toBlob(r,'image/jpeg',.85));}finally{URL.revokeObjectURL(url);}}
document.addEventListener('click',e=>{const sec=e.target.closest('#fph-l1 .cahier');if(!sec)return;
  if(e.target.closest('.cprint'))cahPrint(sec);else if(e.target.closest('.cpdf'))cahPdf(sec,e.target.closest('.cpdf'));});
document.addEventListener('change',async e=>{const inp=e.target;if(!inp.matches||!inp.matches('#fph-l1 .cahier .cphoto input'))return;const f=inp.files&&inp.files[0];if(!f)return;
  const sec=inp.closest('.cahier');let blob=f;try{blob=await photoBlob(f);}catch(x){}
  sendProd({activity:'cahier-'+sec.dataset.cah,label:fr('nb_t')+' '+sec.dataset.cah+' · 📷',mode:'photo',blob,private:true},$('.schip',sec));inp.value='';});

