function fiBlock(el){
  el.insertAdjacentHTML('beforeend',`<div class="ospart"><h3>👔😊 ${fr('fi_t')} ${A(fr('fi_t'))} ${T('fi_t')}</h3>
   <div class="grid g2" style="margin-top:8px">
    <div class="card"><span class="badge fm-w">👔 ${fr('L_formal')}</span> ${T('L_formal')}<div class="small">${fr('L_fw')} · ${fr('L_fs')} · ${fr('L_fd')}</div>
      <div class="li" style="margin-top:8px">❓ ${SW('Comment allez-vous ?','F')}</div><div class="li">💬 ${SW('Très bien, merci. Et vous ?','M')}</div><div class="li">👋 ${SW('Bonne journée !','F')}</div></div>
    <div class="card"><span class="badge fm-i">😊 ${fr('L_informal')}</span> ${T('L_informal')}<div class="small">${fr('L_inf')}</div>
      <div class="li" style="margin-top:8px">❓ ${SW('Ça va ?','Tg')}</div><div class="li">💬 ${SW('Ça va bien, merci. Et toi ?','Tg2')}</div><div class="li">👋 ${SW('À bientôt !','Tg')} ${SW('À demain !','Tg2')}</div></div>
   </div><div style="margin-top:14px">${consigne('fi_c','E')}</div><div class="fiq grid g2"></div><div class="fb fifb" style="text-align:center"></div></div>`);
  const part=el.lastElementChild,g=$('.fiq',part);
  const Q=[['E','Bonjour ! Comment allez-vous ?','👔',['Très bien, merci. Et vous ?','Salut !','Bonne soirée !']],
           ['P','Salut ! Ça va ?','😊',['Ça va bien, merci. Et toi ?','Comment allez-vous ?','Bonsoir, monsieur !']],
           ['E','Au revoir ! Bonne journée !','🕘 9 h · 👋🚪',['Au revoir ! Bonne journée !','Bonsoir !','Bonne soirée !']],
           ['P','Salut ! À demain !','😊 👋🚪',['À demain !','Bonjour !','Comment allez-vous ?']]];
  let n=0,p=0;const K=Kit('fi',part,Q.length);
  Q.forEach(([w,say,ctx,opts],k)=>{const c=document.createElement('div');c.className='card';
    c.innerHTML=`<div class="gsay">${gAv(w)}<div class="gb"><b>${WHO[w][0]} · ${ctx}</b><div class="big" style="font-size:21px">${S(say,WHO[w][1])}</div>${T(EXP[say])}</div></div><div class="ch" style="display:flex;flex-direction:column;gap:8px;margin-top:8px"></div>`;
    const r=$('.ch',c),ans=opts[0];
    shuffle(opts).forEach((o,j)=>{const wr=document.createElement('span');wr.className='opt';const b=choice(o);if(k===0&&j===0)b.dataset.hint=1;wr.appendChild(b);wr.insertAdjacentHTML('beforeend',A(o,WHO[w][1]==='M'?'F':'M'));
      b.onclick=()=>{r.querySelectorAll('.choice').forEach(y=>y.disabled=true);n++;const ok=o===ans;b.classList.add(ok?'ok':'ko');c.classList.add(ok?'ok':'ko');if(ok)p++;else [...r.querySelectorAll('.choice')].find(x=>x.textContent===ans).classList.add('ok');
        speak(ans,{g:WHO[w][1]==='M'?'F':'M'});
        K.answer(ok,()=>{r.querySelectorAll('.choice').forEach(y=>{y.disabled=false;y.classList.remove('ok','ko');});c.classList.remove('ok','ko');c.classList.add('redo');});
        if(n===Q.length){award('fi','CE',p,Q.length);setFb($('.fifb',part),p===Q.length,(p===Q.length?fbOK:fbKO)(p===Q.length?'bravo':'again',`${p}/${Q.length}`));if(p===Q.length)confetti();}};r.appendChild(wr);});
    g.appendChild(c);});
  paintTr(part);}

